// Years from Seder Olam (counting from Creation). Short pages: the immediate
// family, and anything worth knowing.
// `spot` is the name as it appears in the tree checklist (its place on the poster).
const { L, sec, to, nm } = require('./helpers');

const A = 'adam-to-noach';
const N = 'noach-to-terach';
