const one = (titleHe, he, titleEn, en) => [sec(titleHe, he, titleEn, en)];
const B = (ch) => L(`בראשית ${ch}`, `Genesis ${ch}`);

// A nation's father (Bereishit 10). `nation` is the name under him on the poster.
const nation = (slug, he, en, father, nationHe, nationEn, spot, unsure, extra = null) => p({
  slug, cats: [N], name: L(he, en), spot,
  summary: L(`מצאצאיו יצאו ה${nationHe}${unsure ? ' (זיהוי משוער)' : ''}.`, `From him came the ${nationEn}${unsure ? ' (an uncertain identification)' : ''}.`),
  rel: [to('father', father)],
  sources: [L('בראשית י', 'Genesis 10'), L('דברי הימים א׳ א', 'I Chronicles 1'), ...(extra?.sources || [])],
  sections: [
    sec(he, `${he} נמנה בבראשית י בין שבעים האומות שיצאו מבני נח. באילן שלנו כתוב מתחתיו "${nationHe}${unsure ? '?' : ''}"${unsure ? ' – סימן השאלה מציין שהזיהוי של צאצאיו עם עם זה אינו ודאי' : ''}.${extra?.he ? ` ${extra.he}` : ''}`,
      en, `${en} is counted in Genesis 10 among the seventy nations that came from the sons of Noach. On our tree, written under him is "${nationEn}${unsure ? '?' : ''}"${unsure ? ' – the question mark shows that identifying his descendants with this people is not certain' : ''}.${extra?.en ? ` ${extra.en}` : ''}`),
  ],
});

